  'ignore': { ex: 'Please ignore my previous e-mail.', rom: '', ko: '제 이전 이메일은 무시해 주세요.' },
  'civil': { ex: 'The new law protects the civil rights of all workers.', rom: '', ko: '새 법은 모든 노동자의 시민권을 보호해요.' },
  'locate': { ex: 'Our office is located near City Hall.', rom: '', ko: '저희 사무실은 시청 근처에 있어요.' },
  'belief': { ex: 'It\'s our belief that every customer deserves fast service.', rom: '', ko: '저희는 모든 고객이 빠른 서비스를 받아야 한다고 믿어요.' },
  'arrangement': { ex: 'My assistant will make all the travel arrangements.', rom: '', ko: '제 비서가 출장 준비를 모두 할 거예요.' },
