  'acquire': { ex: 'The software giant acquired a small gaming company for 2 million dollars.', rom: '', ko: '그 대형 소프트웨어 회사는 작은 게임 회사를 200만 달러에 인수했어요.' },
  'participate': { ex: 'All employees are encouraged to participate in the survey.', rom: '', ko: '전 직원이 설문 조사에 참여하기를 권장해요.' },
  'representative': { ex: 'A customer service representative will help you shortly.', rom: '', ko: '곧 고객 서비스 담당자가 도와드릴 거예요.' },
  'capacity': { ex: 'The plant is currently operating at full capacity.', rom: '', ko: '그 공장은 현재 최대 생산 능력으로 가동 중이에요.' },
  'border': { ex: 'You need a passport to cross the border.', rom: '', ko: '국경을 넘으려면 여권이 필요해요.' },
  'ad': { ex: 'We placed an ad in the local newspaper.', rom: '', ko: '지역 신문에 광고를 냈어요.' },
  'regulation': { ex: 'The new regulation limits the amount of waste a plant can produce.', rom: '', ko: '새 규정은 공장이 배출할 수 있는 폐기물 양을 제한해요.' },
  'studio': { ex: 'The interview will be recorded in our studio downtown.', rom: '', ko: '인터뷰는 시내에 있는 저희 스튜디오에서 녹화될 거예요.' },
