  'leadership': { ex: 'Under her leadership, sales doubled in two years.', rom: '', ko: '그녀가 이끈 2년 동안 매출이 두 배로 늘었어요.' },
  'bond': { ex: 'There is a strong bond between the two founders.', rom: '', ko: '두 창업자 사이에는 끈끈한 유대가 있어요.' },
  'hire': { ex: 'We plan to hire three new designers.', rom: '', ko: '저희는 새 디자이너 세 명을 고용할 계획이에요.' },
  'internal': { ex: 'This report is for internal use only.', rom: '', ko: '이 보고서는 내부용으로만 써야 해요.' },
  'secure': { ex: 'Our firm secured a major deal with a hotel chain.', rom: '', ko: '저희 회사가 호텔 체인과 큰 계약을 따냈어요.' },
  'rank': { ex: 'Our hotel was ranked first in customer satisfaction.', rom: '', ko: '저희 호텔은 고객 만족도 1위에 올랐어요.' },
  'typical': { ex: 'On a typical day, we receive about 200 orders.', rom: '', ko: '평소에는 하루에 주문이 200건 정도 들어와요.' },
  'resident': { ex: 'Residents are asked to park only in marked spaces.', rom: '', ko: '주민 여러분은 지정된 구역에만 주차해 주세요.' },
  'entirely': { ex: 'I entirely agree with your proposal.', rom: '', ko: '제안하신 내용에 전적으로 동의해요.' },
  'insist': { ex: 'He insisted on paying for dinner.', rom: '', ko: '그는 저녁값을 자기가 내겠다고 고집했어요.' },
  'combination': { ex: 'The dish is a combination of Korean and Italian flavors.', rom: '', ko: '그 요리는 한국 맛과 이탈리아 맛을 섞은 거예요.' },
  'definitely': { ex: 'I\'ll definitely be there on time.', rom: '', ko: '꼭 제시간에 갈게요.' },
  'session': { ex: 'The afternoon session will focus on customer service skills.', rom: '', ko: '오후 세션은 고객 서비스 기술에 초점을 맞출 거예요.' },
  'nevertheless': { ex: 'The weather was bad. Nevertheless, the event was a success.', rom: '', ko: '날씨가 나빴어요. 그런데도 행사는 성공적이었어요.' },
  'protection': { ex: 'Wear eye protection when using this machine.', rom: '', ko: '이 기계를 사용할 때는 보안경을 착용하세요.' },
  'largely': { ex: 'The success of the project was largely due to teamwork.', rom: '', ko: '그 프로젝트가 성공한 건 주로 팀워크 덕분이었어요.' },
  'reasonable': { ex: 'The hotel offers clean rooms at reasonable prices.', rom: '', ko: '그 호텔은 깨끗한 객실을 적당한 가격에 제공해요.' },
  'guarantee': { ex: 'We guarantee delivery within 24 hours.', rom: '', ko: '24시간 이내 배송을 보장해요.' },
  'approve': { ex: 'The director approved our request for new laptops.', rom: '', ko: '이사님이 새 노트북 요청을 승인했어요.' },
  'atmosphere': { ex: 'The café has a warm and friendly atmosphere.', rom: '', ko: '그 카페는 분위기가 따뜻하고 친근해요.' },
  'comparison': { ex: 'This chart shows a comparison of sales in 2025 and 2026.', rom: '', ko: '이 차트는 2025년과 2026년 매출을 비교한 거예요.' },
  'characteristic': { ex: 'Speed is the main characteristic of our new printer.', rom: '', ko: '속도가 저희 새 프린터의 가장 큰 특징이에요.' },
  'rely': { ex: 'Many small shops rely on tourists for most of their sales.', rom: '', ko: '많은 작은 가게들이 매출 대부분을 관광객에게 의존해요.' },
  'narrow': { ex: 'The street is too narrow for large trucks.', rom: '', ko: '그 길은 대형 트럭이 다니기에는 너무 좁아요.' },
  'identity': { ex: 'Please bring a photo ID to confirm your identity.', rom: '', ko: '신원 확인을 위해 사진이 있는 신분증을 가져오세요.' },
  'permit': { ex: 'Smoking is not permitted anywhere in the building.', rom: '', ko: '건물 안에서는 어디서도 흡연이 허용되지 않아요.' },
  'unique': { ex: 'Each design is unique.', rom: '', ko: '디자인 하나하나가 다 독특해요.' },
  'practical': { ex: 'The workshop offers practical tips for managing stress.', rom: '', ko: '그 워크숍에서는 스트레스 관리에 관한 실용적인 팁을 알려 줘요.' },
  'increasingly': { ex: 'Online shopping is becoming increasingly popular.', rom: '', ko: '온라인 쇼핑이 점점 더 인기를 얻고 있어요.' },
  'notion': { ex: 'The notion that older workers can\'t learn new skills is wrong.', rom: '', ko: '나이 든 직원은 새 기술을 못 배운다는 생각은 틀렸어요.' },
  'conservative': { ex: 'The bank takes a conservative approach to lending.', rom: '', ko: '그 은행은 대출에 보수적으로 접근해요.' },
  'opposition': { ex: 'The plan faced strong opposition from local residents.', rom: '', ko: '그 계획은 지역 주민들의 거센 반대에 부딪혔어요.' },
  'arise': { ex: 'Please call me if any problems arise.', rom: '', ko: '문제가 생기면 저에게 전화 주세요.' },
  'recover': { ex: 'The economy is slowly recovering.', rom: '', ko: '경제가 서서히 회복되고 있어요.' },
  'stretch': { ex: 'It\'s good to stand up and stretch every hour.', rom: '', ko: '한 시간마다 일어나서 스트레칭하는 게 좋아요.' },
  'declare': { ex: 'Do you have anything to declare?', rom: '', ko: '신고하실 물품이 있나요?' },
  'tiny': { ex: 'There\'s a tiny scratch on the screen.', rom: '', ko: '화면에 아주 작은 흠집이 있어요.' },
  'analyze': { ex: 'We analyzed the survey results to find out what customers wanted.', rom: '', ko: '고객이 원하는 것을 알아보려고 설문 결과를 분석했어요.' },
  'witness': { ex: 'Two employees witnessed the accident in the parking lot.', rom: '', ko: '직원 두 명이 주차장에서 그 사고를 목격했어요.' },
  'ordinary': { ex: 'It was just an ordinary day at the office.', rom: '', ko: '회사에서는 그냥 평범한 하루였어요.' },
