  'reduction': { ex: 'The new system led to a 20 percent reduction in costs.', rom: '', ko: '새 시스템 덕분에 비용이 20퍼센트 줄었어요.' },
  'reserve': { ex: 'I reserved a room for two nights.', rom: '', ko: '방을 2박으로 예약했어요.' },
  'bore': { ex: 'I won\'t bore you with all the details.', rom: '', ko: '세세한 얘기로 지루하게 해 드리지는 않을게요.' },
  'mission': { ex: 'Our mission is to make healthy food affordable for everyone.', rom: '', ko: '저희의 사명은 누구나 건강한 음식을 부담 없이 먹을 수 있게 하는 거예요.' },
  'somehow': { ex: 'We somehow finished the project on time.', rom: '', ko: '어떻게든 프로젝트를 제때 끝냈어요.' },
  'justice': { ex: 'The victims are still waiting for justice.', rom: '', ko: '피해자들은 아직도 정의가 실현되기를 기다리고 있어요.' },
  'formal': { ex: 'Please wear formal clothes to the awards dinner.', rom: '', ko: '시상식 만찬에는 정장을 입고 오세요.' },
  'reject': { ex: 'The board rejected the proposal.', rom: '', ko: '이사회가 그 제안을 거절했어요.' },
  'frequently': { ex: 'This is one of our most frequently asked questions.', rom: '', ko: '이건 저희가 가장 자주 받는 질문 중 하나예요.' },
  'command': { ex: 'Type this command to restart the program.', rom: '', ko: '프로그램을 다시 시작하려면 이 명령어를 입력하세요.' },
  'impression': { ex: 'She made a good impression at the interview.', rom: '', ko: '그녀는 면접에서 좋은 인상을 남겼어요.' },
