  'via': { ex: 'We\'ll send the documents to you via e-mail.', rom: '', ko: '서류는 이메일로 보내 드릴게요.' },
  'county': { ex: 'The county plans to build a new bridge.', rom: '', ko: '군에서 새 다리를 건설할 계획이에요.' },
  'attach': { ex: 'I\'ve attached the revised file to this e-mail.', rom: '', ko: '수정된 파일을 이 이메일에 첨부했어요.' },
  'acknowledge': { ex: 'He acknowledged that he had made a mistake.', rom: '', ko: '그는 자신이 실수했다는 걸 인정했어요.' },
  'academic': { ex: 'She has an excellent academic record.', rom: '', ko: '그녀는 학업 성적이 아주 뛰어나요.' },
  'meanwhile': { ex: 'The technician is coming soon; meanwhile, please use the other printer.', rom: '', ko: '기술자가 곧 올 거예요. 그동안 다른 프린터를 써 주세요.' },
  'furthermore': { ex: 'The hotel is close to the station. Furthermore, it\'s very affordable.', rom: '', ko: '그 호텔은 역에서 가까워요. 게다가 가격도 아주 저렴해요.' },
  'accuse': { ex: 'He was accused of stealing company data.', rom: '', ko: '그는 회사 데이터를 훔친 혐의로 고발됐어요.' },
  'absence': { ex: 'Mr. Wood will lead the meeting in my absence.', rom: '', ko: '제가 없는 동안 우드 씨가 회의를 진행할 거예요.' },
  'construct': { ex: 'The city plans to construct a new stadium.', rom: '', ko: '시는 새 경기장을 건설할 계획이에요.' },
  'remark': { ex: 'His remarks about the budget surprised everyone.', rom: '', ko: '예산에 관한 그의 발언에 모두 놀랐어요.' },
  'rare': { ex: 'It\'s rare for the train to be late.', rom: '', ko: '기차가 늦는 일은 드물어요.' },
  'intention': { ex: 'We have no intention of raising prices.', rom: '', ko: '저희는 가격을 올릴 생각이 전혀 없어요.' },
  'dozen': { ex: 'Please order two dozen pens for the office.', rom: '', ko: '사무실용으로 펜 두 다스를 주문해 주세요.' },
  'settlement': { ex: 'The two companies reached a settlement out of court.', rom: '', ko: '두 회사는 법정 밖에서 합의에 이르렀어요.' },
  'gap': { ex: 'There\'s a big gap between the two prices.', rom: '', ko: '두 가격 사이에 큰 차이가 있어요.' },
  'minimum': { ex: 'There\'s a minimum order of 50 units.', rom: '', ko: '최소 주문 수량은 50개예요.' },
  'northern': { ex: 'Our northern branch is opening next month.', rom: '', ko: '북부 지점이 다음 달에 문을 열어요.' },
  'equally': { ex: 'The profits will be shared equally among the partners.', rom: '', ko: '수익은 동업자들끼리 똑같이 나눌 거예요.' },
  'expose': { ex: 'Don\'t expose the device to direct sunlight.', rom: '', ko: '기기를 직사광선에 노출시키지 마세요.' },
  'resolve': { ex: 'Our technician resolved the problem within an hour.', rom: '', ko: '저희 기술자가 한 시간 안에 문제를 해결했어요.' },
  'permanent': { ex: 'After six months, she was offered a permanent position.', rom: '', ko: '6개월 후 그녀는 정규직 자리를 제안받았어요.' },
  'emotion': { ex: 'She tried to hide her emotions during the meeting.', rom: '', ko: '그녀는 회의 중에 감정을 감추려고 애썼어요.' },
  'urge': { ex: 'Doctors urge people to get a flu shot.', rom: '', ko: '의사들은 사람들에게 독감 예방 주사를 꼭 맞으라고 권해요.' },
  'appoint': { ex: 'The board appointed Dr. Wilson as the new head of research.', rom: '', ko: '이사회는 윌슨 박사를 새 연구 책임자로 임명했어요.' },
  'stable': { ex: 'The patient\'s condition is now stable.', rom: '', ko: '환자 상태는 이제 안정적이에요.' },
  'merely': { ex: 'I was merely trying to help.', rom: '', ko: '저는 그저 도와드리려던 것뿐이에요.' },
  'vast': { ex: 'The library has a vast collection of old maps.', rom: '', ko: '그 도서관은 옛 지도를 방대하게 소장하고 있어요.' },
  'regional': { ex: 'She was promoted to regional manager.', rom: '', ko: '그녀는 지역 담당 관리자로 승진했어요.' },
  'immediate': { ex: 'We need an immediate response from the client.', rom: '', ko: '고객의 즉각적인 답변이 필요해요.' },
  'incident': { ex: 'Please report any incident to your supervisor.', rom: '', ko: '어떤 사고든 상사에게 보고해 주세요.' },
  'slip': { ex: 'Be careful not to slip on the wet floor.', rom: '', ko: '젖은 바닥에서 미끄러지지 않게 조심하세요.' },
